import { studio, languages, copy } from './content.js';
import { direction } from './direction.js';
const routes=['index.html','design.html','shop.html','studio.html','journal.html','contact.html'];
const page=Number(document.body.dataset.page)||0;
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const safeGet=(key)=>{try{return localStorage.getItem(key)}catch{return null}};
const safeSet=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
let lang=safeGet('stillroom-language')||'en'; if(!copy[lang])lang='en';
let renderVersion=0;
let t=copy[lang],d=direction[lang],slide=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,timer,filter=0,sceneDispose;
const arrow='<span aria-hidden="true">↗</span>';
const sun='<svg class="sun-mark flow-mark" viewBox="0 0 64 64" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 44C8 15 56 15 56 44M8 35C8 6 56 6 56 35M8 53C8 24 56 24 56 53"/></g></svg>';
const image=(i,cls='')=>`<img class="${cls}" src="assets/study-${['rest','form','light'][i]}.jpg" alt="${t.studies[i]}" loading="lazy" width="1200" height="1400">`;
const link=(href,text,cls='text-link')=>`<a class="${cls}" href="${href}">${text}${arrow}</a>`;
function header(){return `<a class="skip-link" href="#main">${t.skip}</a><div class="announcement"><span class="mini-sun">✳</span><a href="shop.html">${t.announcement} <span>${t.soon} ↗</span></a></div><header class="header"><a class="brand" href="index.html" aria-label="${studio.name} ${studio.suffix}">${sun}<span>${studio.name}<small>${studio.suffix}</small></span></a><nav class="desktop-nav" aria-label="${t.menu}">${routes.map((r,i)=>`<a href="${r}" ${i===page?'aria-current="page"':''}>${t.nav[i]}</a>`).join('')}</nav><div class="header-tools"><label class="language-picker"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" aria-hidden="true"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg><span class="sr-only">${t.language}</span><select id="language">${languages.map(([v,l])=>`<option value="${v}" ${lang===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="menu-toggle circle-button" aria-label="${t.menu}" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span></button></div><nav id="mobile-nav" class="mobile-nav" hidden>${routes.map((r,i)=>`<a href="${r}" ${i===page?'aria-current="page"':''}><span>0${i+1}</span>${t.nav[i]}${arrow}</a>`).join('')}</nav></header>`}
function footer(){return `<footer class="footer"><div class="footer-top"><div><div class="eyebrow">${t.tagline}</div><h2>${t.footerTitle}</h2>${link('contact.html',t.footerCta,'button button-dark')}</div><div class="footer-symbol" aria-hidden="true">${sun}</div></div><div class="footer-bottom"><a class="footer-brand" href="index.html">${studio.name}<small>${studio.suffix}</small></a><p>${t.footerNote}</p><nav aria-label="${t.details}">${routes.map((r,i)=>`<a href="${r}">${t.nav[i]}</a>`).join('')}</nav><button class="top-button" aria-label="${t.top}">↑</button></div><div class="footer-wordmark" aria-hidden="true">stillroom<span>®</span></div><div class="legal"><span>© ${new Date().getFullYear()} ${studio.name} ${studio.suffix}. ${t.copyright}</span><span>${t.provisional}</span></div></footer>`}
function hero(){return `<section class="hero" aria-roledescription="carousel" aria-label="${d.eyebrows[0]}" tabindex="0"><div class="hero-copy"><div class="eyebrow slide-eyebrow">${d.eyebrows[0]}</div><h1 class="slide-title">${d.titles[0]}</h1><div class="hero-description"><p class="slide-desc">${t.slides[0][2]}</p><a class="button button-dark slide-link" href="shop.html"><span>${t.explore}</span>${arrow}</a></div><div class="hero-small"><span class="status-dot"></span>${t.productSub}<span class="small-line"></span><span>${t.soon}</span></div></div><div class="hero-art" data-scene="0"><div class="art-backdrop"><span class="backdrop-circle"></span></div><img class="scene-fallback" src="assets/study-rest.jpg" alt="" width="1400" height="1500" fetchpriority="high"><div id="scene" role="img" tabindex="0" aria-label="${t.drag}"></div><div class="art-meta"><span>${d.study} <b>— 001</b></span><span class="art-interact">${t.drag}<span aria-hidden="true">↔</span></span></div><div class="scene-toolbar"><div class="view-toggle" role="group" aria-label="${t.view}"><button data-view="surface" aria-pressed="true">${d.surface}</button><button data-view="structure" aria-pressed="false">${d.structure}</button></div><button class="scene-reset circle-button" aria-label="${d.reset}">↺</button></div><div class="art-disclaimer">${t.visual}</div></div><a href="#chapter01" class="scroll-cue"><span>↓</span>${d.scroll}</a><div class="slider-controls"><div class="slide-dots">${[0,1,2].map(i=>`<button data-slide="${i}" aria-label="${t.slide} ${i+1}" aria-pressed="${i===0}"><span></span></button>`).join('')}</div><span class="slide-count">01 <span>/ 03</span></span><div class="slider-arrows"><button class="circle-button" id="prev" aria-label="${t.prev}">←</button><button class="circle-button" id="pause" aria-label="${paused?t.play:t.pause}">${paused?'▶':'Ⅱ'}</button><button class="circle-button" id="next" aria-label="${t.next}">→</button></div></div><div class="hero-axis" aria-hidden="true">x — y — z</div></section>`}
function productCard(){return `<a class="product-card tilt" href="shop.html"><div class="product-image">${image(0)}<span class="pill">${t.soon}</span><span class="image-arrow">↗</span><span class="image-caption">${t.visual}</span></div><div class="product-caption"><div><span class="eyebrow">${t.productSub} / 001</span><h3>${t.product}</h3></div><span>↗</span></div></a>`}
function journalCards(){return `<div class="journal-grid">${t.articles.map((a,i)=>`<a class="journal-card reveal" href="journal.html?note=${i+1}"><div class="journal-image">${image(i)}<span class="image-arrow">↗</span></div><div class="note-meta"><span>${t.draft}</span><span>0${i+1}</span></div><h3>${a[0]}</h3><p>${a[1]}</p><span class="text-link">${t.read}${arrow}</span></a>`).join('')}</div>`}
function home(){return `${hero()}<div class="principle-strip">${d.principles.map((p,i)=>`<span><small>0${i+1}</small>${p}</span>`).join('')}</div><section id="chapter01" class="intro section-pad reveal"><div class="eyebrow">${t.chapter}</div><div><h2>${t.intro}</h2><div class="intro-bottom"><p>${t.introBody}</p>${link('studio.html',t.learn)}</div></div></section><section class="featured section-pad"><div class="section-heading reveal"><div><div class="eyebrow">${t.featured}</div><h2>${t.productSub}.</h2></div>${link('design.html',t.allDesign)}</div><div class="featured-grid reveal">${productCard()}<div class="featured-aside"><span class="aside-label">${d.label}</span><div class="aside-copy"><div class="eyebrow">${t.productFocus}</div><h3>${t.product}</h3><p>${t.productDesc}</p>${link('shop.html',t.view)}</div><div class="aside-number" aria-hidden="true">01</div></div></div></section><section class="studio-strip reveal"><div class="strip-art">${image(1)}</div><div><div class="eyebrow">${t.approach}</div><h2>${t.studioIntro}</h2><p>${t.studioDesc}</p>${link('studio.html',t.studioLink)}</div></section><section class="journal-section section-pad"><div class="section-heading reveal"><div><div class="eyebrow">${t.nav[4]}</div><h2>${t.homeJournal}</h2></div>${link('journal.html',t.allNotes)}</div>${journalCards()}</section>`}
function pageHeading(eyebrow,title,desc){return `<section class="page-heading section-pad"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p><span class="heading-sun" aria-hidden="true">${sun}</span></section>`}
function design(){return `${pageHeading(t.nav[1],t.workIntro,t.workDesc)}<section class="project-feature section-pad reveal"><div class="project-art tilt">${image(0)}<span class="pill">${t.development}</span><span class="image-caption">${t.visual}</span></div><div class="project-story"><span class="eyebrow">${t.featuredProject}</span><h2>${t.product}</h2><p>${t.productDesc}</p>${link('shop.html',t.view,'button button-dark')}</div></section><section class="process-section section-pad"><div class="section-heading reveal"><div><span class="eyebrow">${t.approach}</span><h2>${t.process}</h2></div><p>${t.processDesc}</p></div><div class="process-grid">${t.steps.map((s,i)=>`<article class="reveal"><span class="process-glyph" aria-hidden="true">${['◒','⌁','✳'][i]}</span><h3>${s}</h3><p>${t.stepBody[i]}</p></article>`).join('')}</div></section><section class="studies-section section-pad"><div class="section-heading reveal"><div><div class="eyebrow">${t.direction}</div><h2>${t.direction.toLocaleLowerCase(lang)}.</h2></div><p>${t.directionDesc}</p></div><div class="filters" role="group" aria-label="${t.direction}">${t.filter.map((v,i)=>`<button data-filter="${i}" aria-pressed="${i===filter}">${v}</button>`).join('')}</div><div class="study-grid">${studyCards()}</div></section>`}
function studyCards(){return t.studies.map((s,i)=>`<button class="study-card tilt" data-study="${i}" ${filter&&filter!==i+1?'hidden':''}><div class="study-image">${image(i)}<span class="image-arrow">+</span></div><span class="note-meta"><span>${t.categories[i]}</span><span>0${i+1}</span></span><span class="study-title">${s}</span></button>`).join('')}
function shop(){return `${pageHeading(t.nav[2],t.shopIntro,t.shopDesc)}<section class="shop-product section-pad"><div class="shop-visual reveal"><div class="shop-image tilt">${image(0)}<span class="pill">${t.soon}</span></div><p class="image-note">${t.visual}</p><div class="product-thumbs">${[0,1,2].map(i=>`<button data-thumb="${i}" aria-label="${t.studies[i]}" aria-pressed="${i===0}">${image(i)}</button>`).join('')}</div></div><div class="shop-info reveal"><span class="eyebrow">${t.productSub} / 001</span><h2>${t.product}</h2><p class="shop-description">${t.productDesc}</p><div class="availability"><span class="status-dot"></span><span>${t.availability}</span></div><p class="purchase-note">${t.productNotice}</p>${link('contact.html?topic=product',t.ask,'button button-dark full-width')}<div class="product-details">${t.info.map((v,i)=>`<details ${i===0?'open':''}><summary>${v}<span aria-hidden="true">+</span></summary><p>${t.infoBody[i]}</p></details>`).join('')}</div></div></section>`}
function studioPage(){return `${pageHeading(t.nav[3],t.studioIntro,t.studioDesc)}<section class="studio-manifesto section-pad"><div class="manifesto-art reveal">${image(1)}<span>${studio.name} / IN THE MAKING</span></div><div class="manifesto-copy reveal"><span class="eyebrow">${t.approach}</span><h2>${t.studioStatement}</h2><p class="draft-note">${t.studioNote}</p></div></section><section class="values section-pad"><div class="eyebrow reveal">${t.approach}</div>${t.values.map((v,i)=>`<article class="value-row reveal"><span>0${i+1}</span><h2>${v}</h2><p>${t.valueBody[i]}</p></article>`).join('')}</section><section class="artist-story section-pad reveal"><div class="artist-symbol">${sun}</div><div><span class="eyebrow">${t.nav[3]}</span><h2>${t.storySoon}</h2><p>${t.storyText}</p>${link('contact.html',t.contact)}</div></section>`}
function journal(){const n=Number(new URLSearchParams(location.search).get('note')); if(n>=1&&n<=3){const a=t.articles[n-1];return `<article class="article-page section-pad"><a class="text-link" href="journal.html">← ${t.back}</a><div class="article-header"><div class="eyebrow">${t.noteLabel} / 0${n} · ${t.draft}</div><h1>${a[0]}</h1><p>${a[1]}</p></div><div class="article-image">${image(n-1)}</div><div class="article-body"><p>${a[2]}</p><p class="draft-note">${t.notesNotice}</p>${link('design.html',t.allDesign)}</div></article>`}return `${pageHeading(t.nav[4],t.journalIntro,t.journalDesc)}<section class="section-pad journal-list">${journalCards()}<p class="draft-note">${t.notesNotice}</p></section>`}
function contactPage(){return `${pageHeading(t.nav[5],t.contactIntro,t.contactDesc)}<section class="contact-section section-pad"><aside class="contact-aside reveal"><div class="contact-sun">${sun}</div><h2>${t.emailSoon}</h2><p>${t.emailHelp}</p><div class="contact-topics">${t.contactTypes.map((v,i)=>`<button data-topic="${i}"><span>0${i+1}</span>${v} ↗</button>`).join('')}</div></aside><form id="enquiry-form" class="enquiry-form reveal"><div class="form-row"><label>${t.name}<input name="name" autocomplete="name" required maxlength="120"></label><label>${t.email}<input name="email" type="email" autocomplete="email" required maxlength="254"></label></div><label>${t.topic}<select name="topic">${t.contactTypes.map((v,i)=>`<option value="${i}">${v}</option>`).join('')}</select></label><label>${t.message}<textarea name="message" rows="5" required minlength="10" maxlength="5000" placeholder="${t.messagePlaceholder}"></textarea></label><p class="form-hint">${t.formHint}</p><div class="form-actions"><button class="button button-dark" type="submit">${t.send}${arrow}</button><button class="text-link" id="download-enquiry" type="button">${t.download} ↓</button></div><p id="form-status" role="status" aria-live="polite"></p></form></section>`}
function render(){const version=++renderVersion;sceneDispose?.();document.body.classList.remove('menu-open');clearInterval(timer);document.documentElement.lang=lang;document.body.dataset.lang=lang;document.title=`${t.nav[page]} — ${studio.name} ${studio.suffix}`;document.querySelector('meta[name="description"]').content=page===2?t.productDesc:t.introBody;document.getElementById('app').innerHTML=header()+`<main id="main">${[home,design,shop,studioPage,journal,contactPage][page]()}</main>`+footer()+`<dialog class="study-dialog"><button class="dialog-close circle-button" aria-label="${t.modalClose}">×</button><div class="dialog-content"></div></dialog>`;bind();if(page===0){setSlide(slide,false);import('./scene.js').then(m=>{if(version===renderVersion&&$('#scene'))sceneDispose=m.mountScene($('#scene'),{reduced:paused,slide})}).catch(()=>{});startTimer()}}
function setSlide(i,animate=true){slide=(i+3)%3;const heroEl=$('.hero');if(!heroEl)return;heroEl.dataset.active=slide;const s=t.slides[slide];$('.slide-eyebrow').textContent=d.eyebrows[slide];$('.slide-title').innerHTML=d.titles[slide];$('.slide-desc').textContent=s[2];$('.slide-link').href=slide===2?'journal.html':'shop.html';$('.slide-link span').textContent=slide===2?t.allNotes:t.explore;$('.slide-count').innerHTML=`0${slide+1} <span>/ 03</span>`;$$('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.slide)===slide));$('.hero-art').dataset.scene=slide;const fallback=$('.scene-fallback');fallback.src=`assets/study-${['rest','form','light'][slide]}.jpg`;if(animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches){$('.hero-copy').animate([{opacity:.15,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'ease-out'})}window.dispatchEvent(new CustomEvent('stillroom-slide',{detail:slide}));}
function startTimer(){clearInterval(timer);if(!paused&&!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>setSlide(slide+1),7500)}
function bind(){
 $('#language').addEventListener('change',e=>{lang=e.target.value;t=copy[lang];d=direction[lang];safeSet('stillroom-language',lang);render()});
 $('.menu-toggle').addEventListener('click',e=>{const b=e.currentTarget,open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',!open);b.setAttribute('aria-label',open?t.menu:t.close);$('#mobile-nav').hidden=open;document.body.classList.toggle('menu-open',!open)});
 $('.header').addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded',false);document.body.classList.remove('menu-open');$('.menu-toggle').focus()}});
 $('.top-button').addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target)}}),{threshold:.08});$$('.reveal').forEach(el=>io.observe(el));
 $$('.tilt').forEach(el=>{el.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect();el.style.setProperty('--rx',`${-(e.clientY-r.top-r.height/2)/r.height*5}deg`);el.style.setProperty('--ry',`${(e.clientX-r.left-r.width/2)/r.width*5}deg`)});el.addEventListener('pointerleave',()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg')})});
 if(page===0){$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{$$('[data-view]').forEach(v=>v.setAttribute('aria-pressed',v===b));window.dispatchEvent(new CustomEvent('stillroom-view',{detail:b.dataset.view}))}));$('.scene-reset').addEventListener('click',()=>window.dispatchEvent(new CustomEvent('stillroom-reset')));$$('[data-slide]').forEach(b=>b.addEventListener('click',()=>{setSlide(Number(b.dataset.slide));startTimer()}));$('#next').addEventListener('click',()=>{setSlide(slide+1);startTimer()});$('#prev').addEventListener('click',()=>{setSlide(slide-1);startTimer()});$('#pause').addEventListener('click',e=>{paused=!paused;e.currentTarget.innerHTML=paused?'▶':'Ⅱ';e.currentTarget.setAttribute('aria-label',paused?t.play:t.pause);window.dispatchEvent(new CustomEvent('stillroom-motion',{detail:paused}));startTimer()});$('.hero').addEventListener('mouseenter',()=>clearInterval(timer));$('.hero').addEventListener('mouseleave',startTimer);$('.hero').addEventListener('focusin',()=>clearInterval(timer));$('.hero').addEventListener('focusout',startTimer);$('.hero').addEventListener('keydown',e=>{if(e.target.closest('select, #scene'))return;if(e.key==='ArrowRight'){e.preventDefault();setSlide(slide+1)}if(e.key==='ArrowLeft'){e.preventDefault();setSlide(slide-1)}});let startX;$('.hero-copy').addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX},{passive:true});$('.hero-copy').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>50){setSlide(slide+(dx<0?1:-1));startTimer()}},{passive:true})}
 $$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=Number(b.dataset.filter);$$('[data-filter]').forEach(v=>v.setAttribute('aria-pressed',v===b));$$('[data-study]').forEach(v=>v.hidden=filter!==0&&Number(v.dataset.study)+1!==filter)}));
 $$('[data-study]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.study);$('.dialog-content').innerHTML=image(i)+`<div class="dialog-caption"><h2>${t.studies[i]}</h2><p>${t.visual}</p></div>`;$('.study-dialog').showModal()}));$('.dialog-close').addEventListener('click',()=>$('.study-dialog').close());$('.study-dialog').addEventListener('click',e=>{if(e.target===$('.study-dialog'))e.target.close()});
 $$('[data-thumb]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.thumb);$('.shop-image img').src=`assets/study-${['rest','form','light'][i]}.jpg`;$('.shop-image img').alt=t.studies[i];$$('[data-thumb]').forEach(v=>v.setAttribute('aria-pressed',v===b))}));
 if(page===5)bindForm();
}
function bindForm(){const form=$('#enquiry-form');let draft;try{draft=JSON.parse(safeGet('stillroom-enquiry')||'{}')}catch{draft={}};for(const k of ['name','email','message'])if(draft[k])form.elements[k].value=draft[k];form.elements.topic.value=new URLSearchParams(location.search).get('topic')==='product'?'0':draft.topic||'0';const save=()=>{const values=Object.fromEntries(new FormData(form));safeSet('stillroom-enquiry',JSON.stringify(values));$('#form-status').textContent=t.saved};form.addEventListener('input',save);form.addEventListener('change',save);$$('[data-topic]').forEach(b=>b.addEventListener('click',()=>{form.elements.topic.value=b.dataset.topic;form.elements.message.focus();save()}));const getText=()=>`${studio.name} ${studio.suffix}\n${t.topic}: ${t.contactTypes[Number(form.elements.topic.value)]}\n${t.name}: ${form.elements.name.value}\n${t.email}: ${form.elements.email.value}\n\n${form.elements.message.value}`;form.addEventListener('submit',async e=>{e.preventDefault();save();try{await navigator.clipboard.writeText(getText());$('#form-status').textContent=t.copied}catch{$('#form-status').textContent=t.copyFail}});$('#download-enquiry').addEventListener('click',()=>{if(!form.reportValidity())return;save();const url=URL.createObjectURL(new Blob([getText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='stillroom-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');motionQuery.addEventListener('change',e=>{paused=e.matches;window.dispatchEvent(new CustomEvent('stillroom-motion',{detail:paused}));if($('#pause')){$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?t.play:t.pause)}startTimer()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInterval(timer);else if(page===0)startTimer()});
render();
